Object.assign(vectorPaths,{components:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 17h7 M17.5 14v7',figma:'M12 3H8a4 4 0 0 0 0 8h4z M12 3h4a4 4 0 0 1 0 8h-4z M12 11H8a4 4 0 0 0 0 8h4z M12 19v1a4 4 0 1 1-4-4 M20 15a4 4 0 1 1-8 0 4 4 0 0 1 8 0',agent:'M12 3v3 M8 3h8 M5 7h14v12H5z M8 12h1 M15 12h1 M9 16h6 M2 10v6 M22 10v6',company:'M4 21V3h11v18 M15 9h5v12 M8 7h3 M8 11h3 M8 15h3 M2 21h20',pod:'M12 3l4 3v5l-4 3-4-3V6z M4 13l4 3v5H2v-5z M20 13l-4 3v5h6v-5z M12 14v6 M8 18h8'});
const typeIcon=t=>({'Skill':'code','MCP Server':'plug','Plugin':'layers','Repository':'folder','Product':'box','Agent Package':'users','Command':'terminal','Workflow Template':'layers'})[t]||'box';
const verifiedBaseIcons={'github-mcp':'https://github.com/github.png?size=64','langflow':'https://github.com/langflow-ai.png?size=64','autogen':'https://github.com/microsoft.png?size=64','mcp-reference':'https://github.com/modelcontextprotocol.png?size=64','docassemble':'https://github.com/jhpyle.png?size=64','eyecite':'https://github.com/freelawproject.png?size=64','courtlistener':'https://github.com/freelawproject.png?size=64'};
function resourceIcon(d){const original=d.icon||verifiedBaseIcons[d.id];const url=window.CATALOGUE_ICON_CACHE?.[original]||original;return `<span class="resource-icon" title="${url?'Publisher image':'Resource type icon'}">${svgIcon(typeIcon(d.type))}${url?`<img src="${esc(url)}" alt="${esc(d.owner)} publisher image" loading="lazy" referrerpolicy="no-referrer">`:''}</span>`;}
function wireImages(){$$('.resource-icon img').forEach(img=>{img.onerror=()=>img.remove();});}
let catalogueWorker=null,requestNo=0,requests=new Map(),cataloguePage=1,catalogueQueryKey='',queryRevision=0,sourceSelection='all';
function callCatalogue(action,payload={}){if(!catalogueWorker){catalogueWorker=new Worker('../shared/catalogue-worker.js');catalogueWorker.onmessage=({data})=>{const pending=requests.get(data.request);if(!pending)return;requests.delete(data.request);data.error?pending.reject(Error(data.error)):pending.resolve(data);};catalogueWorker.onerror=()=>{for(const p of requests.values())p.reject(Error('Catalogue worker could not load. Open this website through the localhost preview.'));requests.clear();};}return new Promise((resolve,reject)=>{const request=++requestNo;requests.set(request,{resolve,reject});catalogueWorker.postMessage({action,request,...payload});});}
const knownRecords=new Set(D.map(d=>d.id));
function retainRecords(records){for(const d of records)if(!knownRecords.has(d.id)){knownRecords.add(d.id);D.push(d);}}
function routeTypes(){const bits=location.hash.slice(2).split('/'),route=bits[0],sourceRoute=bits[2];const extra=additionalCatalogueSections.find(s=>s.route===route);if(extra)return [extra.type];const map={skills:['Skill'],'mcp-servers':['MCP Server'],plugins:['Plugin'],products:['Product'],marketplace:['Product','Plugin'],repositories:['Plugin','Repository'],technical:['Skill','MCP Server','Plugin','Repository'],agents:['Agent Package'],subagents:['Agent Package'],commands:['Command'],workflows:['Workflow Template'],automations:['Workflow Template']};return map[route==='source'?sourceRoute:route]||[];}
function navLeaf(route,label,icon,count){return `<a href="#/${route}" title="${esc(label)}">${svgIcon(icon)}<span>${esc(label)}</span>${count!=null?`<small>${Number(count).toLocaleString()}</small>`:''}</a>`;}
function sourceTree(s){return `<details class="nav-level-two"><summary>${svgIcon('globe')}<span>${esc(s.name)}</span>${svgIcon('chevron')}</summary><div>${navLeaf('source/'+s.id,'All listings','grid',s.count)}${[['skills','Skill','code'],['mcp-servers','MCP Server','plug'],['plugins','Plugin','layers'],['products','Product','box']].filter(([,t])=>s.types[t]).map(([r,t,i])=>navLeaf('source/'+s.id+'/'+r,t==='Plugin'?'Plugins & marketplaces':t+'s',i,s.types[t])).join('')}</div></details>`;}
function sidebar(){const count=t=>IMPORT.sources.reduce((n,s)=>n+(s.types[t]||0),0);return `<aside class="universal-sidebar" aria-label="Catalogue navigation"><div class="side-heading"><a href="#/discover">${svgIcon('layers')}<span>${esc(B.name)}</span></a><button id="closeNavigation" aria-label="Close navigation">${svgIcon('close')}</button></div><button class="side-search global-search">${svgIcon('search')}<span>Search catalogue</span><kbd>⌘ K</kbd></button><nav><div class="side-label">WORKSPACE</div>${navLeaf('discover','Overview','grid')}${navLeaf('saved','Saved resources','bookmark')}<details open class="nav-level-one"><summary>${svgIcon('box')}<span>Explore catalogue</span>${svgIcon('chevron')}</summary><div>${navLeaf('products','Products','box',count('Product'))}${navLeaf('skills','Skills','code',count('Skill'))}${navLeaf('mcp-servers','MCP servers','plug',count('MCP Server'))}${navLeaf('plugins','Plugins & marketplaces','layers',count('Plugin'))}${navLeaf('repositories','Repositories','github')}${additionalCatalogueSections.map(s=>navLeaf(s.route,s.label,s.icon,count(s.type))).join('')}</div></details><details class="nav-level-one"><summary>${svgIcon('globe')}<span>Reference websites</span>${svgIcon('chevron')}</summary><div>${IMPORT.sources.map(sourceTree).join('')}</div></details><details class="nav-level-one"><summary>${svgIcon('book')}<span>Resources & company</span>${svgIcon('chevron')}</summary><div>${[['docs','Documentation'],['how-to-install','Installation guide'],['blog','Articles'],['catalogue-coverage','Import coverage'],['submit','Submit a resource'],['about','About'],['contact','Contact']].map(([r,t])=>navLeaf(r,t,'book')).join('')}</div></details></nav><div class="side-foot"><span class="status-dot"></span><span>${IMPORT.total.toLocaleString()} indexed listings<small>4 reference websites · 7 designs</small></span></div></aside><button class="navigation-scrim" aria-label="Close navigation panel"></button>`;}
const priorShellCatalogue=shell;
shell=function(){priorShellCatalogue();$('.template-sidebar')?.remove();document.body.classList.add('with-catalogue-sidebar');document.body.insertAdjacentHTML('afterbegin',sidebar());const header=$('.topbar')||$('.template-top');header?.insertAdjacentHTML('afterbegin',`<button id="navigationToggle" aria-label="Toggle catalogue navigation" aria-expanded="true">${svgIcon('panel')}</button>`);$('#openSidebar')?.remove();$('#navigationToggle').onclick=()=>{if(innerWidth<=1000)document.body.classList.toggle('catalogue-nav-open');else document.body.classList.toggle('catalogue-nav-closed');$('#navigationToggle').setAttribute('aria-expanded',innerWidth<=1000?document.body.classList.contains('catalogue-nav-open'):!document.body.classList.contains('catalogue-nav-closed'));};const close=()=>document.body.classList.remove('catalogue-nav-open');$('#closeNavigation').onclick=close;$('.navigation-scrim').onclick=close;$$('.universal-sidebar a').forEach(a=>a.addEventListener('click',close));$('.side-search').onclick=openSearch;const mode=$('#mode');mode.options[0].textContent='Imported catalogue';if(!$('#savedCount'))$('.review-dock>div').insertAdjacentHTML('beforeend','<a href="#/saved">Saved <span id="savedCount"></span></a>');document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();$('.code-explorer')?.classList.remove('expanded');}});callCatalogue('init').catch(()=>{});};
card=function(d){return `<article class="card imported-card ${V===2?'registry-row':''}"><div class="catalogue-card-head">${resourceIcon(d)}<span class="type-label">${esc(d.type)}</span><button data-save="${d.id}" aria-label="${state.saved.includes(d.id)?'Unsave':'Save'} ${esc(d.name)}" aria-pressed="${state.saved.includes(d.id)}">${svgIcon('bookmark')}</button></div><h3><a href="${href(d)}">${esc(d.name)}</a></h3><p>${esc(d.summary)}</p><div class="catalogue-card-meta"><span>${esc(d.sourceSite||d.owner)}</span><span class="coverage-badge ${d.indexOnly?'index-only':''}">${d.indexOnly?'Index entry':d.demo?'Demo':'Metadata'}</span></div><div class="catalogue-card-actions"><a href="${href(d)}">Explore resource ${svgIcon('arrow')}</a><button data-compare="${d.id}" aria-label="Compare ${esc(d.name)}">+</button></div></article>`;};
const priorSearchCatalogue=searchView;
searchView=function(kind='discover',items=pool(),title){let out=priorSearchCatalogue(kind,items,title);out=out.replace('Source samples','Indexed listings').replace(/SOURCE SAMPLES/g,'PUBLIC INDEX');const sourceBar=`<section class="catalogue-source-bar"><label>Source<select id="catalogueSource"><option value="all">All four websites</option>${IMPORT.sources.map(s=>`<option value="${s.id}">${esc(s.name)} · ${s.count.toLocaleString()}</option>`).join('')}</select></label><div><strong>${IMPORT.total.toLocaleString()}</strong> listings <span>·</span> <a href="#/catalogue-coverage">Import coverage</a></div></section>`;out=out.replace(/<fieldset><legend>(Resource type|Component type)<\/legend>[\s\S]*?<\/fieldset>/,()=>'<fieldset><legend>Resource type</legend>'+allTypeNames.map(t=>'<label><input type="checkbox" data-type="'+esc(t)+'">'+esc(t)+'</label>').join('')+'</fieldset>');out=out.replace(/<div class="categories">[\s\S]*?<\/div>/,()=>'<div class="categories">'+['All','Skills','MCP Servers','Marketplaces','Products','Repositories','Commands'].map(c=>'<button class="chip" data-category="'+c+'">'+c+'</button>').join('')+'</div>');out=out.replace(/<select id="categorySelect"[\s\S]*?<\/select>/,()=>'<select id="categorySelect" aria-label="Category">'+['All','Skills','MCP Servers','Marketplaces','Products','Repositories','Commands'].map(c=>'<option>'+c+'</option>').join('')+'</select>');return out.replace('<form class="searchbox"',sourceBar+'<form class="searchbox"');};
const priorWireSearchCatalogue=wireSearch;
wireSearch=function(items){priorWireSearchCatalogue(items);const r=location.hash.slice(2).split('/');if(r[0]==='source')sourceSelection=r[1];const select=$('#catalogueSource');if(select){select.value=sourceSelection;select.onchange=()=>{sourceSelection=select.value;cataloguePage=1;paintCards();};}let timer;$('#search').oninput=e=>{state.query=e.target.value;clearTimeout(timer);timer=setTimeout(()=>{cataloguePage=1;paintCards();},160);};paintCards();};
const originalLocalPaint=paintCards;
paintCards=async function(){if(state.mode==='demo'&&!additionalCatalogueSections.some(s=>s.route===location.hash.slice(2).split('/')[0])){originalLocalPaint();wireImages();return;}const target=$('#cards');if(!target)return;const bits=location.hash.slice(2).split('/'),source=bits[0]==='source'?bits[1]:sourceSelection,route=bits[0];const filters={query:state.query,types:additionalCatalogueSections.some(s=>s.route===route)?routeTypes():(state.types.length?state.types:routeTypes()),source,category:state.category,sort:state.sort,officialOnly:route==='official',savedOnly:state.savedOnly||route==='saved',saved:state.saved,limit:24};const key=JSON.stringify(filters);if(key!==catalogueQueryKey){catalogueQueryKey=key;cataloguePage=1;}const revision=++queryRevision;target.setAttribute('aria-busy','true');if(!target.children.length)target.innerHTML='<div class="catalogue-loading">Loading the public catalogue…</div>';try{const result=await callCatalogue('search',{...filters,page:cataloguePage});if(revision!==queryRevision||target!==$('#cards'))return;if(route==='saved'){const locals=D.filter(d=>!d.imported&&state.saved.includes(d.id));if(result.page===1)result.records.unshift(...locals);result.total+=locals.length;}retainRecords(result.records);target.innerHTML=result.records.length?result.records.map(card).join(''):'<div class="empty"><h3>No matching listings</h3><p>'+ (additionalCatalogueSections.some(s=>s.route===route)?'No items in this section match the current catalogue and filters. New items can be added to this category as the library grows.':'Try another search or source filter.') +'</p><button data-reset>Clear filters</button></div>';$('#count').textContent=result.total.toLocaleString()+' resources';let pager=$('#cataloguePager');if(!pager){target.insertAdjacentHTML('afterend','<nav id="cataloguePager" aria-label="Catalogue pages"></nav>');pager=$('#cataloguePager');}pager.innerHTML=`<button id="previousPage" ${result.page===1?'disabled':''}>← Previous</button><label>Page <input id="pageNumber" type="number" min="1" max="${result.pages}" value="${result.page}" aria-label="Catalogue page number"> of ${result.pages.toLocaleString()}</label><button id="goPage">Go</button><button id="nextPage" ${result.page===result.pages?'disabled':''}>Next →</button><small>${result.total?((result.page-1)*24+1).toLocaleString():0}–${Math.min(result.page*24,result.total).toLocaleString()} of ${result.total.toLocaleString()}</small>`;const change=n=>{cataloguePage=Math.max(1,Math.min(result.pages,n||1));paintCards();target.scrollIntoView({block:'start',behavior:'smooth'});};$('#previousPage').onclick=()=>change(result.page-1);$('#nextPage').onclick=()=>change(result.page+1);$('#goPage').onclick=()=>change(+$('#pageNumber').value);$('#pageNumber').onkeydown=e=>{if(e.key==='Enter')change(+e.target.value);};wireCards();wireImages();}catch(e){if(target===$('#cards'))target.innerHTML=`<div class="empty"><h3>Catalogue unavailable</h3><p>${esc(e.message)}</p><button id="retryCatalogue">Retry loading</button></div>`;$('#retryCatalogue')&&($('#retryCatalogue').onclick=()=>paintCards());}finally{target.removeAttribute('aria-busy');}};
let globalSearchRevision=0;
paintGlobalSearch=async function(){const revision=++globalSearchRevision;$('#globalResults').innerHTML='<p>Searching all four catalogues…</p>';try{const r=await callCatalogue('search',{query:$('#globalQuery').value,limit:20});if(revision!==globalSearchRevision)return;retainRecords(r.records);$('#globalResults').innerHTML=`<small>${r.total.toLocaleString()} matching listings</small>`+r.records.map(d=>`<a href="${href(d)}">${resourceIcon(d)}<strong>${esc(d.name)}</strong><span>${esc(d.type)} · ${esc(d.sourceSite)}</span></a>`).join('');$$('#globalResults a').forEach(a=>a.onclick=()=>$('#searchDialog').close());wireImages();}catch(e){$('#globalResults').textContent=e.message;}};
const oldSetupCatalogue=setupCommand;
setupCommand=function(d){return d.imported?(d.installCommand||'# Setup guide: '+(d.docs||d.listingUrl)):oldSetupCatalogue(d);};
resourceHeader=function(d){return `<div class="resource-heading">${resourceIcon(d)}<div><h1>${esc(d.name)}</h1><div class="badges">${badge(d.type)}${badge(d.sourceCategory||d.category)}${d.official?badge('Source marks publisher official'):''}</div></div></div><p class="resource-summary">${esc(d.summary)}</p><div class="resource-owner">${esc(d.owner)} · ${esc(d.sourceSite||'Source sample')}</div>`;};
detail=function(d){return `<div class="breadcrumb">${link('discover','Home')} › ${link('technical',esc(d.type))} › ${esc(d.name)}</div><article class="catalogue-detail"><div class="component-hero"><div><section class="component-identity">${resourceHeader(d)}</section>${d.indexOnly?'<p class="index-notice">Index record · title derived from the listing URL. Full publisher metadata and official imagery are not available in this snapshot.</p>':''}${installPanel(d)}<div class="meta-buttons">${external(d.listingUrl||d.source,'Original listing')}<button data-save="${d.id}" aria-label="Save ${esc(d.name)}">${svgIcon('bookmark')} Save</button><button data-compare="${d.id}">Compare +</button><button data-stack="${d.id}">+ Add to stack</button></div></div>${terminal(d)}</div>${editor(d)}<div class="resource-layout"><article>${readme(d)}${d.listingUrl?`<section class="source-trace"><h2>Source record</h2><p>${esc(d.sourceSite)} · captured ${IMPORT.captured}</p>${external(d.listingUrl,'View original directory listing')}${external(d.source,'Publisher / source documentation')}<p>${d.indexOnly?'Public listing index imported. Metadata, files and logo not retrieved.':'Public catalogue metadata imported. Source claims are preserved; this is not an independent audit.'}</p></section>`:''}</article>${detailAside(d)}</div></article>`;};
appendLandingSections=function(){if(!$('#cards'))return;const chosen=D.find(d=>d.id==='github-mcp')||D[0];const target=$('.home-bottom')||$('.template-directory');if(!target)return;target.insertAdjacentHTML('afterend',`<section class="landing-workbench"><div class="section-heading"><div><small>EXPLORE THE COMPONENT</small><h2>Inspect the code. Preview the setup.</h2></div>${link('item/'+chosen.id,'Open '+esc(chosen.name)+' →')}</div><div class="landing-workbench-grid">${editor(chosen)}${terminal(chosen)}</div></section>`);};
function coveragePage(){return `<section class="page-title"><div class="eyebrow">IMPORT / ${IMPORT.captured}</div><h1>${IMPORT.total.toLocaleString()} public listing records</h1><p>Every qualifying listing in the retrieved public sitemaps is searchable. Metadata coverage is reported separately.</p></section><div class="coverage-grid">${IMPORT.sources.map(s=>`<section><h2>${esc(s.name)}</h2><strong>${s.count.toLocaleString()}</strong><p>Indexed listings</p><dl><dt>With imported metadata</dt><dd>${s.metadataCount.toLocaleString()}</dd><dt>Index records only</dt><dd>${s.indexOnlyCount.toLocaleString()}</dd><dt>Sitemap files checked</dt><dd>${s.sitemapCount}</dd></dl>${link('source/'+s.id,'Browse this source →')}</section>`).join('')}</div><article class="readme"><h2>What the labels mean</h2><p>Metadata records have names and available publisher fields from public catalogue pages or APIs. Index entries preserve listing URLs; their display names are derived from URL slugs, and generic vector icons are used when an authoritative image is unavailable.</p><p>The same resource can appear in multiple source directories. These records stay separate, with source labels. Published sitemaps can include stale records or omit newly added resources. This snapshot is not a claim that every current source record has complete metadata.</p><p>MCP Market rate-limited its metadata API. Its complete public sitemap index was retained; only successfully retrieved metadata pages were enriched. Installation windows are visual previews and execute no commands.</p></article>`;}
routes.push('catalogue-coverage');
const priorRenderCatalogue=render;let routeRevision=0;
render=function(){const revision=++routeRevision;const bits=location.hash.slice(2).split('/'),r=bits[0]||'discover',id=bits[1];if(r==='item'&&id?.startsWith('import-')&&!knownRecords.has(id)){$('#main').innerHTML='<section class="page-title"><h1>Loading resource…</h1></section>';callCatalogue('get',{id}).then(result=>{if(revision!==routeRevision)return;if(result.record){retainRecords([result.record]);render();}else $('#main').innerHTML='<h1>Resource not found</h1>';}).catch(e=>{$('#main').innerHTML='<h1>Could not load resource</h1><p>'+esc(e.message)+'</p>';});return;}if(r==='source'){terminalCancel++;sourceSelection=id;$('#main').innerHTML=searchView(r,[],IMPORT.sources[+id]?.name||'Source catalogue');wireSearch([]);document.title=B.name+' — Source catalogue';}else if(r==='catalogue-coverage'){terminalCancel++;$('#main').innerHTML=coveragePage();document.title=B.name+' — Import coverage';}else if(r==='official'){terminalCancel++;$('#main').innerHTML=searchView('discover',[],'Source publishers');wireSearch([]);}else priorRenderCatalogue();document.body.dataset.page=r;$$('.universal-sidebar a').forEach(a=>a.setAttribute('aria-current',a.hash===location.hash?'page':'false'));document.body.classList.remove('catalogue-nav-open');if(r==='discover'){const d=D.find(d=>d.id==='github-mcp')||D[0];wireResource(d);const stat=$('.template-stats a strong');if(stat)stat.textContent=IMPORT.total.toLocaleString();}wireImages();};

const priorResetCatalogue=resetFilters;resetFilters=function(){priorResetCatalogue();sourceSelection='all';cataloguePage=1;};
const priorInstallCatalogue=installPanel;installPanel=function(d){let html=priorInstallCatalogue(d);if(d.imported)html=html.replace('Downloads source code only; follow the maintainer’s setup guide.',d.installCommand?'Source-provided command · preview only · not executed':'No installation command imported. Open the publisher setup guide.');return html;};
categoryPage=function(){return '<section class="page-title"><h1>Explore the catalogue</h1><p>Browse every imported record by resource type or original directory.</p></section><div class="link-grid">'+[['products','Product','box'],['skills','Skill','code'],['mcp-servers','MCP Server','plug'],['plugins','Plugin','layers'],['repositories','Repository','folder'],['commands','Command','terminal']].map(([r,t,i])=>'<a class="link-tile" href="#/'+r+'">'+svgIcon(i)+'<h2>'+t+'s</h2><strong>'+IMPORT.sources.reduce((n,s)=>n+(s.types[t]||0),0).toLocaleString()+'</strong></a>').join('')+'</div><h2>Original directories</h2><div class="link-grid">'+IMPORT.sources.map(s=>'<a class="link-tile" href="#/source/'+s.id+'"><h3>'+esc(s.name)+'</h3>'+s.count.toLocaleString()+' listings</a>').join('')+'</div>';};

const catalogueWireResource=wireResource;wireResource=function(d){catalogueWireResource(d);if($('.landing-workbench .file-tree')){$('.landing-workbench .file-tree').classList.add('hidden');$('#toggleFiles').setAttribute('aria-expanded','false');}};
const catalogueWireCards=wireCards;wireCards=function(){catalogueWireCards();$$('[data-save]').forEach(b=>{const original=b.onclick;b.onclick=function(e){original?.call(this,e);this.innerHTML=svgIcon('bookmark')+(this.closest('.meta-buttons')?' Save':'');this.setAttribute('aria-pressed',state.saved.includes(this.dataset.save));};});};

// Dedicated catalogue routes shared by every brand variation.
for(const s of additionalCatalogueSections)if(!routes.includes(s.route))routes.push(s.route);
const renderBeforeAdditionalSections=render;
render=function(){const section=additionalCatalogueSections.find(s=>s.route===location.hash.slice(2).split('/')[0]);if(!section)return renderBeforeAdditionalSections();terminalCancel++;let html=searchView(section.route,[],section.label);html=html.replace(/<fieldset><legend>Resource type<\/legend>[\s\S]*?<\/fieldset>/,'').replace(/<div class="categories">[\s\S]*?<\/div>/,'');html='<div class="additional-catalogue-intro" style="display:flex;align-items:center;gap:12px;margin:20px 0;color:var(--muted)">'+svgIcon(section.icon)+'<p style="margin:0">'+esc(section.description)+'</p></div>'+html;$('#main').innerHTML=html;wireSearch([]);wireCards();document.title=B.name+' — '+section.label;document.body.dataset.page=section.route;document.body.classList.remove('catalogue-nav-open');$$('.universal-sidebar a').forEach(a=>a.setAttribute('aria-current',a.hash===location.hash?'page':'false'));};
const renderBeforeNativeComponents=render;render=function(){const componentRoute=location.hash.slice(2).split('/')[0];if(!['ui-components','figma-templates'].includes(componentRoute))return renderBeforeNativeComponents();terminalCancel++;window.renderComponentryNative($('#main'),B.id,window.COMPONENTRY_NATIVE_ASSET_BASE,componentRoute);document.title=B.name+' — '+(componentRoute==='figma-templates'?'Figma Components':'UI Components Library');document.body.dataset.page=componentRoute;document.body.classList.remove('catalogue-nav-open');$$('.universal-sidebar a').forEach(a=>a.setAttribute('aria-current',a.hash===location.hash?'page':'false'));};
const categoryPageBeforeAdditionalSections=categoryPage;categoryPage=function(){return categoryPageBeforeAdditionalSections()+'<h2>More to explore</h2><div class="link-grid">'+additionalCatalogueSections.map(s=>'<a class="link-tile" href="#/'+s.route+'">'+svgIcon(s.icon)+'<h2>'+esc(s.label)+'</h2><p>'+esc(s.description)+'</p></a>').join('')+'</div>';};
